// 에피소드 — 옆자리 사람과 나누는 짧은 오디오 대화
// 모든 대사는 이 앱을 위해 새로 작성했어요.
//
// 듣기: 다 알아들을 필요 없어요. 들리는 단어 몇 개와 말투(어감)로 뜻을 끼워 맞춰요.
// 말하기: 하고 싶은 말을 내가 고르고, 핵심 단어만 말하면 통해요.
//
// 대사 형식
//   { narr: '상황 설명' }
//   { them: { ja, ko, mean, keys, tone? } }
//       keys  들리면 뜻이 보이는 핵심 단어. 한글 발음이 문장의 한글 발음 안에 그대로 있어야 해요.
//       tone  (선택) 말투 설명을 직접 적을 때. 없으면 문장 끝(か, の, ね, よ …)을 보고 알려 줘요.
//   { me: [ 할 수 있는 말 1, 할 수 있는 말 2 … ] }
//       intent   하고 싶은 말 (한국어)
//       words    이 말에 필요한 핵심 단어. 이 중 하나만 들려도 통해요.
//       natural  이렇게 말하면 자연스러워요: ['일본어', '한글 발음', '뜻']
//       react    (선택) 이 말을 골랐을 때 상대 반응: { ja, ko, mean }
//
//   변주 (선택) them.alt: [{ ja, ko, keys }] 같은 뜻 다른 말투. 판마다 기본 또는 alt 중 하나를 골라 들려줘요 (뜻은 기본과 같아야 해요)
//   가지 (선택) 대답의 go: '꼬리표' → 이 대답을 고르면 꼬리표가 붙어요. 차례의 when: '꼬리표' → 그 꼬리표가 있을 때만 나와요
//       건너뛴 차례는 안 보이는 빈 브릭(p:1)으로 채워 브릭 번호 = 차례 번호를 지켜요. 고친 뒤엔 npm run check
// 단어 형식: ['かな|漢字', '한글 발음', '뜻'] — 첫 표기를 소리로 읽고, 모든 표기를 음성 인식에서 맞다고 봐요.

